  // ---------- חילוק ארוך ----------
  function longDiv(n, d) {
    var s = String(n), st = [], rem = 0, started = false, carried = false;
    for (var i = 0; i < s.length; i++) {
      var dig = +s[i], cur = rem * 10 + dig;
      if (!started && cur < d && i < s.length - 1) { rem = cur; carried = true; continue; }
      var pre = i > 0 && started ? 'מורידים את הספרה ' + dig + ' ומקבלים ' + cur + '. ' : (carried ? 'הספרה הראשונה קטנה מ-' + d + ', אז לוקחים שתי ספרות: ' + cur + '. ' : '');
      started = true;
      var qd = Math.floor(cur / d), r = cur - qd * d;
      st.push({ show: M(cur) + ' ÷ ' + d, q: pre + 'כמה פעמים ' + d + ' נכנס ב-' + cur + '?', a: qd, hint: 'מחפשים את המספר הכי גדול ש-' + d + ' כפול הוא לא עובר את ' + cur + '. למשל ' + d + ' × ' + qd + ' = ' + d * qd + '.' });
      if (r && i < s.length - 1) st.push({ show: cur + ' − ' + M(d + ' × ' + qd), q: 'כמה נשאר? ' + cur + ' − ' + d * qd + ' = ?', a: r, hint: d + ' × ' + qd + ' = ' + d * qd + '. מחסירים מ-' + cur + '.' });
      rem = r; carried = false;
    }
    st.push({ show: n + ' ÷ ' + d, q: 'כותבים את הספרות שמצאתם לפי הסדר. מה התשובה?', a: n / d, hint: 'כל תשובה של "כמה פעמים נכנס" היא ספרה אחת בתשובה.' });
    return st;
  }
