      { m: 'A ↔ D , B ↔ E , C ↔ F', t: 'הסדר של האותיות חשוב: A מתאים ל-D, B ל-E ו-C ל-F. לכן הצלע AB שווה לצלע DE, והזווית B שווה לזווית E.' },
      { m: he('צ.ז.צ · ז.צ.ז · צ.צ.צ'), t: 'משפטי החפיפה: שתי צלעות והזווית שביניהן, צלע ושתי הזוויות שלידה, או שלוש צלעות. מספיק אחד מהם כדי לקבוע שהמשולשים חופפים.' },
      { m: SV_ISO, t: 'במשולש שווה שוקיים שתי צלעות שוות, השוקיים. זוויות הבסיס שוות זו לזו.' },
      { m: '180° − 2 · 50° = <b class="ok">80°</b>', t: 'אם זווית בסיס היא חמישים, גם השנייה חמישים, וזווית הראש מאה שמונים פחות מאה, שמונים.' },
      { m: he('חוצה זווית הראש = גובה = תיכון'), t: 'ועוד תכונה: במשולש שווה שוקיים, חוצה זווית הראש הוא גם הגובה לבסיס וגם התיכון לבסיס. הוא חוצה את הבסיס לשני חצאים.' }
