      return { ex: he('מגבלות:') + ' x + y ≤ ' + c1 + ' , ' + a2 + 'x + y ≤ ' + c2 + ' , x, y ≥ 0<br>' + he('רווח:') + ' P = ' + px + 'x + ' + py + 'y<br>' + he(lv === 2 ? 'מצאו את קודקוד החיתוך של שתי המגבלות ואת הרווח בו.' : 'מצאו את הרווח המקסימלי.'), steps: st, fin: lv === 3 ? 'P max = ' + Math.round(best * 100) / 100 : '(' + x0 + ', ' + y0 + ') · P = ' + (px * x0 + py * y0) };
