      { m: 'P(x > 190) = 2.14 + 0.13 = <b class="ok">2.27%</b>', t: 'לכן אחוז האנשים שגבוהים ממאה תשעים: שני הפסים הקיצוניים, שתיים נקודה שתיים שבע אחוז. בבחינה יש גרף עם האחוזים האלה.' }
