      { m: he('עבודה: ') + F(1, 3) + ' + ' + F(1, 6) + ' = ' + F(1, 2) + ' → <b class="ok">2</b> ' + he('שעות'), t: 'בבעיות עבודה מחשבים כמה עושים בשעה אחת. מי שמסיים בשלוש שעות עושה שליש בשעה. מי שמסיים בשש עושה שישית. יחד הם עושים חצי בשעה, ולכן יסיימו בשתי שעות.' }
