      { m: he('אלכסון התיבה:') + ' √(a² + b² + c²)', t: 'ואלכסון התיבה הוא יתר במשולש עומד: אלכסון הבסיס והגובה. יוצא שורש של שלושת הריבועים יחד.' },
      { m: '2 × 3 × 6 → √(4 + 9 + 36) = √49 = <b class="ok">7</b>', t: 'למשל תיבה שתיים על שלוש על שש: ארבע ועוד תשע ועוד שלושים ושש, ארבעים ותשע. השורש שבע.' },
      { m: 'tan α = ' + F(he('גובה'), he('אלכסון הבסיס')), t: 'והזווית בין אלכסון התיבה לבסיס: במשולש העומד, הגובה הוא הנגדי ואלכסון הבסיס הוא הליד. לכן טנגנס הזווית הוא הגובה חלקי אלכסון הבסיס.' }
