      { m: '(3 + 4i) + (1 − 2i) = 4 + 2i', t: 'בחיבור, מחברים ממשי עם ממשי ומדומה עם מדומה.' },
      { m: '(2 + i)(3 + 4i) = 6 + 8i + 3i + 4' + M('i²') + '<br>= 6 − 4 + 11i = <b class="ok">2 + 11i</b>', t: 'בכפל, פותחים סוגריים כמו תמיד, ובסוף זוכרים ש-i בריבוע הוא מינוס אחת. ארבע i בריבוע הופך למינוס ארבע.' },
      { m: '|3 + 4i| = √(3² + 4²) = <b class="ok">5</b>', t: 'הערך המוחלט הוא המרחק מראשית הצירים: שורש של סכום הריבועים. כמו פיתגורס.' },
      { m: 'z̄ = 3 − 4i', t: 'והצמוד: הופכים את הסימן של החלק המדומה. מספר כפול הצמוד שלו נותן תמיד מספר ממשי.' }
